use std::error::Error;

use infra_http::HttpContract;
use utoipa_axum::router::OpenApiRouter;
// template:begin authn:service-api-authn-imports
use utoipa::Modify;
use utoipa::openapi::security::{HttpAuthScheme, HttpBuilder, SecurityScheme};
// template:end authn:service-api-authn-imports
use utoipa::OpenApi;
use utoipa::openapi::OpenApi as Document;

use crate::AppState;

const GENERATED_HEADER: &str =
    "# Generated by `make openapi-generate` from the Rust contract; do not edit by hand.";

/// Document identity. `version` and `license` follow this crate's Cargo
/// metadata; the title names the service the way the repository does.
#[derive(OpenApi)]
#[openapi(
    info(
        title = "rust-service-template-rest",
        description = "HTTP contract served by the `service` binary: platform probes and feature operations, with RFC 9457 problem responses from one closed catalog. An unknown path returns a 404 Problem. An unsupported method returns a 405 Problem with Allow. The HTTP listener can reject oversized request headers with 431 before routing."
    ),
    servers((url = "/", description = "current service origin")),
    tags(
        (name = "system", description = "Operational endpoints for liveness and readiness."),
        // template:begin inbound-webhooks:service-api-webhooks-tag
        (name = "webhooks", description = "Authenticated inbound webhook admission.")
        // template:end inbound-webhooks:service-api-webhooks-tag
    ),
    // template:begin authn:service-api-authn-document-security
    modifiers(&BearerAuth),
    security(("bearerAuth" = []))
    // template:end authn:service-api-authn-document-security
)]
struct ApiDoc;

// template:begin authn:service-api-authn-security-scheme
struct BearerAuth;

impl Modify for BearerAuth {
    fn modify(&self, document: &mut Document) {
        document
            .components
            .get_or_insert_with(utoipa::openapi::Components::new)
            .add_security_scheme(
                "bearerAuth",
                SecurityScheme::Http(HttpBuilder::new().scheme(HttpAuthScheme::Bearer).build()),
            );
    }
}
// template:end authn:service-api-authn-security-scheme

#[derive(Debug, thiserror::Error)]
pub enum ContractError {
    #[error(transparent)]
    Finalization(#[from] infra_http::FinalizeError),
    // template:begin http-idempotency:service-api-contract-error-idempotency
    #[error(transparent)]
    Idempotency(#[from] infra_http::idempotency::CompositionError),
    // template:end http-idempotency:service-api-contract-error-idempotency
    #[error("render the OpenAPI document as YAML: {0}")]
    Yaml(#[source] Box<dyn Error + Send + Sync>),
}

pub fn contract() -> Result<HttpContract<AppState>, ContractError> {
    Ok(HttpContract::new(assemble()).with_probes("/"))
}

fn assemble() -> OpenApiRouter<AppState> {
    OpenApiRouter::with_openapi(ApiDoc::openapi())
        // template:begin inbound-webhooks:service-api-webhooks-router
        .merge(infra_webhooks::inbound::route::router())
    // template:end inbound-webhooks:service-api-webhooks-router
}

pub fn document() -> Result<Document, ContractError> {
    Ok(contract()?.into_openapi()?)
}

pub fn render() -> Result<String, ContractError> {
    let yaml = document()?
        .to_yaml()
        .map_err(|err| ContractError::Yaml(Box::new(err)))?;
    Ok(format!("{GENERATED_HEADER}\n{}\n", yaml.trim_end()))
}

// template:begin authn:service-api-protected-test-route
#[cfg(test)]
mod tests {
    use axum::http::StatusCode;
    use axum::http::header::AUTHORIZATION;
    use axum::response::IntoResponse;

    use super::*;

    #[utoipa::path(
        get,
        path = "/_test/protected",
        tag = "system",
        operation_id = "testProtected",
        summary = "Test-only protected composition seam",
        security(("bearerAuth" = [])),
        extensions(("x-security-decision" = json!({
            "exposure": "protected",
            "rationale": "test-only route proving the production bearer composition seam"
        }))),
        responses(
            (status = 200, description = "verified", content_type = "text/plain", body = String),
            infra_http::authn::ProtectedOperationProblemResponses,
        )
    )]
    async fn protected(
        principal: infra_http::VerifiedPrincipal,
        headers: axum::http::HeaderMap,
    ) -> impl IntoResponse {
        let authorization_was_removed = !headers.contains_key(AUTHORIZATION);
        let identity_was_verified = !principal.issuer().is_empty()
            && (principal.subject().is_some() || principal.client_id().is_some());
        if authorization_was_removed && identity_was_verified {
            (StatusCode::OK, "verified").into_response()
        } else {
            StatusCode::INTERNAL_SERVER_ERROR.into_response()
        }
    }

    fn public_check(
        document: Document,
    ) -> Result<infra_http::Application, infra_http::FinalizeError> {
        HttpContract::new(OpenApiRouter::with_openapi(document)).build(
            (),
            infra_http::Authentication::Public,
            &infra_http::HardenOptions {
                max_body_bytes: 1024,
                request_timeout: std::time::Duration::from_secs(1),
                max_in_flight: None,
                admission_wait: std::time::Duration::ZERO,
                log_health_probes: false,
                draining: None,
            },
        )
    }

    #[test]
    fn protected_contract_refuses_public_finalization_without_a_composer() {
        let document = assemble()
            .routes(utoipa_axum::routes!(protected))
            .into_openapi();
        assert!(matches!(
            public_check(document),
            Err(infra_http::FinalizeError::ProtectedOperation { .. })
        ));
    }

    #[test]
    fn public_probe_contract_does_not_depend_on_a_verifier() {
        let document = HttpContract::new(assemble())
            .with_probes("/")
            .into_openapi()
            .expect("valid probe contract");
        assert!(public_check(document).is_ok());
    }
}
// template:end authn:service-api-protected-test-route
// template:begin http-idempotency:service-api-idempotent-test-route
#[cfg(test)]
mod idempotency_tests {
    use axum::http::StatusCode;
    use infra_http::idempotency::{self, FreshCommand, ReplayableResponse, Rollback, Tx};

    use super::*;

    #[utoipa::path(
        post,
        path = "/_test/idempotent",
        tag = "system",
        operation_id = "testIdempotent",
        summary = "Test-only idempotent composition seam",
        security(("bearerAuth" = [])),
        extensions(
            ("x-security-decision" = json!({
                "exposure": "protected",
                "rationale": "test-only route proving the production idempotency composition seam"
            }))
        ),
        responses(
            (status = 201, description = "created", content_type = "text/plain", body = String),
            infra_http::authn::ProtectedOperationProblemResponses,
        )
    )]
    async fn idempotent(_input: ()) -> Result<Create, infra_http::Problem> {
        Ok(Create)
    }

    #[derive(OpenApi)]
    #[openapi(paths(idempotent))]
    struct IdempotentDocument;

    struct Create;

    impl FreshCommand for Create {
        async fn execute(self, _: &mut Tx<'_>) -> Result<ReplayableResponse, Rollback> {
            let headers = axum::http::HeaderMap::from_iter([(
                axum::http::header::CONTENT_TYPE,
                axum::http::HeaderValue::from_static("text/plain"),
            )]);
            ReplayableResponse::bytes(StatusCode::CREATED, &headers, "created".into())
        }
    }

    fn test_route() -> HttpContract<AppState> {
        idempotency::route(IdempotentDocument::openapi(), idempotent).expect("test route composes")
    }

    #[test]
    fn test_only_idempotent_route_generates_the_served_contract() {
        let contract = contract().unwrap().merge(test_route());
        assert_eq!(contract.idempotent_operations(), 1);
        let document = serde_json::to_value(contract.into_openapi().unwrap()).unwrap();
        let operation = &document["paths"]["/_test/idempotent"]["post"];
        assert!(operation.get("x-idempotent").is_none());
        let parameters = operation["parameters"].as_array().unwrap();
        let key = parameters
            .iter()
            .find(|parameter| parameter["name"] == "Idempotency-Key")
            .expect("composition adds the key parameter");
        assert_eq!(key["in"], "header");
        assert_eq!(key["required"], true);
        assert_eq!(key["schema"]["type"], "string");
        assert!(key["schema"].get("maxLength").is_none());
        assert!(key["schema"].get("pattern").is_none());
        for (status, component) in [
            ("401", "AuthenticationUnauthorized"),
            ("403", "AuthenticationForbidden"),
            ("408", "RequestTimeout"),
            ("409", "IdempotencyRequestInProgress"),
            ("413", "RequestEntityTooLarge"),
            ("422", "IdempotencyKeyMismatch"),
            ("500", "InternalServerError"),
        ] {
            assert_eq!(
                operation["responses"][status]["$ref"],
                format!("#/components/responses/{component}")
            );
        }
        for (status, header) in [("400", "WWW-Authenticate"), ("503", "Retry-After")] {
            let response = &operation["responses"][status];
            assert!(
                response["content"]
                    .get("application/problem+json")
                    .is_some()
            );
            assert!(response["headers"].get(header).is_some());
        }
        assert_eq!(operation["responses"]["201"]["description"], "created");
        assert_eq!(
            operation["responses"]["201"]["headers"]["Idempotent-Replayed"]["schema"],
            serde_json::json!({ "type": "string", "enum": ["true"] })
        );
    }

    #[test]
    fn constructing_an_unmounted_route_leaves_the_service_inactive() {
        let service = contract().unwrap();
        drop(test_route());
        assert_eq!(service.idempotent_operations(), 0);
    }
}
// template:end http-idempotency:service-api-idempotent-test-route
